from __future__ import annotations

def survival_probability(p: float, edge_set_size: int) -> float:
    """Exact probability that a fixed edge set of a given size survives: p**|S|."""
    return p ** edge_set_size

def demonstrate_fragility(p: float, lengths: list[int]) -> list[tuple[int, float]]:
    """Tabulate the survival probability of a single fixed cycle as it lengthens.
    Illustrates that p**L -> 0, i.e. a single prescribed long cycle is doomed."""
    return [(L, survival_probability(p, L)) for L in lengths]

if __name__ == "__main__":
    for L, prob in demonstrate_fragility(0.9, [1, 5, 10, 50, 100, 200]):
        print(f"length {L:4d}: survival probability = {prob:.6e}")

from __future__ import annotations
import random

Edge = tuple[int, int]

def min_degree(n: int, edges: list[Edge]) -> int:
    deg = [0] * n
    for a, b in edges:
        deg[a] += 1; deg[b] += 1
    return min(deg) if deg else 0

def longest_path_length(n: int, edges: list[Edge]) -> int:
    """Longest simple-path length by exhaustive DFS (small graphs)."""
    adj: list[set[int]] = [set() for _ in range(n)]
    for a, b in edges:
        adj[a].add(b); adj[b].add(a)
    best = 0
    def dfs(v: int, visited: set[int], length: int) -> None:
        nonlocal best
        best = max(best, length)
        for w in adj[v]:
            if w not in visited:
                visited.add(w); dfs(w, visited, length + 1); visited.remove(w)
    for s in range(n):
        dfs(s, {s}, 0)
    return best

def percolate(edges: list[Edge], p: float, rng: random.Random) -> list[Edge]:
    return [e for e in edges if rng.random() < p]

if __name__ == "__main__":
    rng = random.Random(7); n = 8
    host = [(i, j) for i in range(n) for j in range(i + 1, n)]
    for p in [0.4, 0.6, 0.8]:
        kept = percolate(host, p, rng)
        d = min_degree(n, kept); lp = longest_path_length(n, kept)
        print(f"p={p}: min-degree={d}, longest path={lp}, path >= min-degree: {lp >= d}")

